const error = $json;
const executionUrl = $('On workflow error').first().json.execution?.url ?? '';
const lines = [
  `Workflow: ${error.workflow}`,
  `Node: ${error.node ?? 'n/a'}`,
  `Batch: ${error.batch_id ?? 'n/a'}`,
  `Error: ${error.message}`,
  executionUrl ? `Execution: ${executionUrl}` : null,
].filter(Boolean);

return {
  json: {
    message: {
      FromEmailAddress: $env.SES_FROM,
      Destination: { ToAddresses: [$env.SES_FROM] },
      Content: {
        Simple: {
          Subject: { Data: `[loan-engine] ${error.workflow} failed`, Charset: 'UTF-8' },
          Body: { Text: { Data: lines.join('\n'), Charset: 'UTF-8' } },
        },
      },
    },
  },
};
